export default {
    name: 'c_input_number',
    props: {
        name: {
            type: String
        },
        configData:{
            type:null
        }
    },
    data () {
        return {
            defaults: {},
            sliderWidth: 0,
            datas: this.configData,
            max: Infinity
        }
    },
    mounted () {},
    watch: {
         configData: {
            handler (nVal, oVal) {
                nVal[this.name].val = Number(nVal[this.name].val)
                this.datas = nVal
            },
            immediate: true,
            deep: true
        }
    },
    methods: {
        numberVal(val){
            let r = /^\+?[1-9][0-9]*$/;
            if(!r.test(val)){
                this.datas[this.name].val = 3;
            }
        },
        maxNum(val){
            if(val>=50){
                this.max = 50
                this.datas[this.name].val = 50;
            }
        }
    }
}
